-- EXPLAIN of a partitioned table scans the partitions pruning keeps
-- (partprune.c): an Append of their scans named pt_1, pt_2, ... as
-- ruleutils.c names the range table, one surviving partition scanned
-- under the table's own name, and a Result with a false One-Time Filter
-- when none survives. RANGE, LIST with NULL and default partitions, HASH,
-- multi-column RANGE, boolean LIST and multi-level partitioning.
CREATE TABLE pt600 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE pt600_1 PARTITION OF pt600 FOR VALUES FROM (1) TO (10);
CREATE TABLE pt600_2 PARTITION OF pt600 FOR VALUES FROM (10) TO (20);
INSERT INTO pt600 SELECT g, g FROM generate_series(1, 19) g;
EXPLAIN (COSTS OFF) SELECT * FROM pt600;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 3;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE 3 = id;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE v = 3;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id < 12;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id BETWEEN 3 AND 8;
EXPLAIN (COSTS OFF) SELECT count(*) FROM pt600;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id > 100;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 3 AND id = 15;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 5 + 1;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 5::bigint;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id::numeric = 5;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id IN (1, 12);
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 1 OR id = 2;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE v = 1 AND v = 2;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 3 ORDER BY v;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 WHERE id = 300 ORDER BY v;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 ORDER BY id LIMIT 2;
EXPLAIN (COSTS OFF) SELECT * FROM ONLY pt600;
EXPLAIN (COSTS OFF) SELECT * FROM pt600 x WHERE x.id > 4;
EXPLAIN (COSTS OFF) SELECT * FROM (SELECT * FROM pt600 WHERE id < 5) s;
EXPLAIN (COSTS OFF) SELECT (SELECT max(v) FROM pt600) AS m;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM pt600;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM pt600 WHERE id = 3;
EXPLAIN (VERBOSE, COSTS OFF) SELECT count(*) FROM pt600 WHERE v = 3;
EXPLAIN (VERBOSE, COSTS OFF) SELECT sum(v) FROM pt600;
EXPLAIN (VERBOSE, COSTS OFF) SELECT v + 1 FROM pt600 WHERE v > 1 ORDER BY 1;
EXPLAIN (FORMAT JSON, COSTS OFF) SELECT * FROM pt600 WHERE id > 5;
EXPLAIN (FORMAT JSON, COSTS OFF) SELECT 1 UNION ALL SELECT 2;
CREATE TABLE lt600 (k text, v int) PARTITION BY LIST (k);
CREATE TABLE lt600_ab PARTITION OF lt600 FOR VALUES IN ('a', 'b');
CREATE TABLE lt600_c PARTITION OF lt600 FOR VALUES IN ('c');
CREATE TABLE lt600_n PARTITION OF lt600 FOR VALUES IN (NULL);
CREATE TABLE lt600_d PARTITION OF lt600 DEFAULT;
EXPLAIN (COSTS OFF) SELECT * FROM lt600;
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k = 'a';
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k = 'z';
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k IS NULL;
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k IS NOT NULL;
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k <> 'c';
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k NOT IN ('a', 'b');
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k IN ('a', 'c');
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k > 'b';
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k = 'a' OR k IS NULL;
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k = 'x' OR v = 1;
EXPLAIN (COSTS OFF) SELECT * FROM lt600 WHERE k = NULL;
CREATE TABLE r600 (a int, b int) PARTITION BY RANGE (a, b);
CREATE TABLE r600_1 PARTITION OF r600 FOR VALUES FROM (MINVALUE, MINVALUE) TO (1, 10);
CREATE TABLE r600_2 PARTITION OF r600 FOR VALUES FROM (1, 10) TO (1, 20);
CREATE TABLE r600_3 PARTITION OF r600 FOR VALUES FROM (1, 20) TO (5, MAXVALUE);
CREATE TABLE r600_d PARTITION OF r600 DEFAULT;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a = 1;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a = 1 AND b = 15;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a = 1 AND b < 10;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a < 1;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a > 4;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a >= 1 AND b > 25;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE b = 3;
EXPLAIN (COSTS OFF) SELECT * FROM r600 WHERE a = 7;
CREATE TABLE h600 (a int, b text) PARTITION BY HASH (a, b);
CREATE TABLE h600_0 PARTITION OF h600 FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE h600_1 PARTITION OF h600 FOR VALUES WITH (MODULUS 4, REMAINDER 1);
CREATE TABLE h600_2 PARTITION OF h600 FOR VALUES WITH (MODULUS 2, REMAINDER 0);
EXPLAIN (COSTS OFF) SELECT * FROM h600;
EXPLAIN (COSTS OFF) SELECT * FROM h600 WHERE a = 1 AND b = 'x';
EXPLAIN (COSTS OFF) SELECT * FROM h600 WHERE a = 2 AND b = 'y';
EXPLAIN (COSTS OFF) SELECT * FROM h600 WHERE a = 1;
EXPLAIN (COSTS OFF) SELECT * FROM h600 WHERE a IS NULL AND b IS NULL;
EXPLAIN (COSTS OFF) SELECT * FROM h600 WHERE a = 3 AND b IS NULL;
CREATE TABLE bp600 (f bool, v int) PARTITION BY LIST (f);
CREATE TABLE bp600_t PARTITION OF bp600 FOR VALUES IN (true);
CREATE TABLE bp600_f PARTITION OF bp600 FOR VALUES IN (false);
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE f;
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE NOT f;
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE f IS TRUE;
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE f IS NOT TRUE;
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE f = false;
EXPLAIN (COSTS OFF) SELECT * FROM bp600 WHERE f <> true AND v = 1;
CREATE TABLE ml600 (a int, b int, c text) PARTITION BY RANGE (a);
CREATE TABLE ml600_1 PARTITION OF ml600 FOR VALUES FROM (0) TO (10) PARTITION BY LIST (b);
CREATE TABLE ml600_1a PARTITION OF ml600_1 FOR VALUES IN (1, 2);
CREATE TABLE ml600_1b PARTITION OF ml600_1 FOR VALUES IN (3);
CREATE TABLE ml600_1d PARTITION OF ml600_1 DEFAULT;
CREATE TABLE ml600_2 PARTITION OF ml600 FOR VALUES FROM (10) TO (20);
CREATE TABLE ml600_d PARTITION OF ml600 DEFAULT;
EXPLAIN (COSTS OFF) SELECT * FROM ml600;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE a = 5;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE a = 5 AND b = 3;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE b = 3;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE a >= 20;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE a IS NULL;
EXPLAIN (COSTS OFF) SELECT * FROM ml600 WHERE a <> 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a FROM ml600 WHERE a = 5;
CREATE TABLE ck600 (a int, v int NOT NULL) PARTITION BY RANGE (a);
CREATE TABLE ck600_1 PARTITION OF ck600 (CHECK (v > 0)) FOR VALUES FROM (0) TO (10);
CREATE TABLE ck600_2 PARTITION OF ck600 FOR VALUES FROM (10) TO (20);
EXPLAIN (COSTS OFF) SELECT * FROM ck600 WHERE v < 0;
EXPLAIN (COSTS OFF) SELECT * FROM ck600 WHERE v IS NULL;
EXPLAIN (COSTS OFF) SELECT * FROM ck600 WHERE v > 5 AND v < 3;
EXPLAIN (COSTS OFF) SELECT * FROM ck600 WHERE v = 1 OR v = 2;
